<script lang="ts">
  import {tick} from 'svelte';
  import {goto,invalidateAll} from '$app/navigation';
  import {page} from '$app/state';
  import {manufacturerAssetKinds,manufacturerAssetScopes,type ManufacturerAssetInput} from '@schubert/contracts';
  import {command} from '#lib/client/api.ts';
  import {uploadOriginal} from '#lib/client/uploads.ts';
  import {focusTrap} from '#lib/client/focus-trap.ts';
  import {searchableSelect} from '#lib/client/searchable-select.ts';
  import type {AppData,Row} from '#lib/client/types.ts';
  import Icon from './Icon.svelte';
  let {data}:{data:AppData}=$props();
  $effect(()=>{if(error)void tick().then(()=>{const alert=document.querySelector<HTMLElement>('[role="dialog"] .notice.error');alert?.setAttribute('tabindex','-1');alert?.focus();alert?.scrollIntoView({block:'nearest'});});});
  let editing:Row|null=$state(null),open=$state(false),stage=$state(1),busy=$state(false),error=$state(''),notice=$state('');
  let uploadAbort:AbortController|null=$state(null);
  let file:File|null=$state(null),fileInput=$state<HTMLInputElement>();
  let values:ManufacturerAssetInput=$state(empty());
  let usePlanning=$state(true),useAI=$state(false),rights=$state(''),confirmed=$state(false),archiveCandidate=$state('');
  let query=$state(page.url.searchParams.get('q')??''),scope=$state(page.url.searchParams.get('studio')??''),kind=$state(page.url.searchParams.get('kind')??'');
  const current=$derived(editing?data.records.find(row=>row.id===editing?.id)??editing:null);
  const fileReady=$derived(current?.file_status==='available'&&current?.version_status==='available');
  const canAI=$derived(['application/pdf','image/png','image/jpeg','image/webp','image/tiff'].includes(current?.mime_type??''));
  function empty():ManufacturerAssetInput{return{name:'',manufacturer_name:'',article_reference:'',kind:'plan',studio_scope:'both',source_url:'',source_unit:null,notes:''};}
  function start(row:Row|null=null){editing=row;values=row?{name:row.name,manufacturer_name:row.manufacturer_name,article_reference:row.article_reference,kind:row.kind,studio_scope:row.studio_scope,source_url:row.source_url,source_unit:row.source_unit,notes:row.notes}:empty();file=null;error='';confirmed=false;rights=row?.rights_statement??'';usePlanning=row?.use_planning??true;useAI=row?.use_ai??false;stage=row?.document_version_id?2:1;open=true;}
  function close(){if(busy)return;open=false;editing=null;file=null;error='';}
  async function save(event:SubmitEvent){
    event.preventDefault();busy=true;error='';notice='';
    try{
      let result=await command(editing?'manufacturer.asset.update':'manufacturer.asset.create',editing?.id,values,editing?.version);
      editing=result;notice='Quellenangaben sind gespeichert. Die Originaldatei wird jetzt übertragen.';
      if(file){uploadAbort=new AbortController();const doc=await uploadOriginal(file,'manufacturer-assets',result.id,uploadAbort.signal);result=await command('manufacturer.asset.attach',result.id,{document_id:doc.id},result.version);editing={...result,file_name:doc.name,mime_type:doc.mime_type,file_status:doc.status,version_status:doc.status};file=null;}
      await invalidateAll();stage=2;
      notice='Entwurf gespeichert. Prüfen Sie jetzt Datei und erlaubte Verwendung.';
    }catch(problem){notice=editing?'Quellenangaben gespeichert. Die Dateiübertragung ist beendet; den Dateistand vor einer Wiederholung prüfen.':'';error=(editing?'Der Quellenentwurf ist gespeichert. Die Dateiverknüpfung konnte noch nicht bestätigt werden. Erneutes Speichern setzt denselben Entwurf fort. ':'')+(problem instanceof Error?problem.message:'Die Unterlage konnte nicht gespeichert werden.');}
    finally{busy=false;uploadAbort=null;}
  }
  async function publish(event:SubmitEvent){
    event.preventDefault();if(!current||!fileReady)return;busy=true;error='';
    try{await command('manufacturer.asset.publish',current.id,{use_planning:usePlanning,use_ai:useAI,rights_statement:rights,rights_confirmed:confirmed},current.version);await invalidateAll();notice='Die Herstellerunterlage ist jetzt in den ausgewählten Studios verfügbar.';busy=false;close();}
    catch(problem){error=problem instanceof Error?problem.message:'Die Unterlage konnte nicht bereitgestellt werden.';}
    finally{busy=false;}
  }
  async function archive(row:Row){busy=true;error='';try{await command('manufacturer.asset.archive',row.id,{},row.version);archiveCandidate='';await invalidateAll();notice='Die Unterlage ist aus der neuen Auswahl ausgeblendet. Vorhandene Quellenbezüge bleiben erhalten.';}catch(problem){error=(problem as Error).message;}finally{busy=false;}}
  function filters(){const params=new URLSearchParams();if(query.trim())params.set('q',query.trim());if(scope)params.set('studio',scope);if(kind)params.set('kind',kind);return params;}
  async function search(event:Event){event.preventDefault();await goto('/manufacturer-assets?'+filters());}
  function next(){const params=filters();params.set('after',data.summary.manufacturerLibrary.nextCursor);return '/manufacturer-assets?'+params;}
  function chooseFile(event:Event){file=(event.currentTarget as HTMLInputElement).files?.[0]??null;if(file&&!values.name)values.name=file.name.replace(/\.[^.]+$/,'').replace(/[_-]+/g,' ');}
  function modalFocus(node:HTMLElement){const opener=document.activeElement as HTMLElement|null;const trap=focusTrap(node);return{destroy(){trap.destroy();void tick().then(()=>{if(opener?.isConnected)opener.focus();});}};}
  function status(row:Row){return row.status==='available'?'In den Studios verfügbar':row.document_version_id&&row.file_status!=='available'?'Dateiprüfung offen':row.document_version_id?'Verwendung festlegen':'Datei ergänzen';}
</script>

<div class="page-heading"><div><h1>Herstellerbibliothek</h1><p>Originale einmal ablegen. In beiden Studios mit der richtigen Quelle planen.</p></div><div class="page-heading-actions">{#if data.context?.role==='SuperAdmin'}<a class="btn" href="/settings?tab=users"><Icon name="users" size={16}/>Zugriff vergeben</a>{/if}<button class="btn primary" onclick={()=>start()}><Icon name="plus" size={17}/>Herstellerunterlage hinzufügen</button></div></div>
<div class="library-intro"><div><span>1</span><p><strong>Original hinzufügen</strong>Grundriss, Kontur, Datenblatt oder Herstellerfoto.</p></div><div><span>2</span><p><strong>Studio zuordnen</strong>Grabmal, Raum & Naturstein oder beide.</p></div><div><span>3</span><p><strong>Verwendung festlegen</strong>Planvorlage und KI-Nutzung getrennt erlauben.</p></div></div>
{#if notice&&!open}<div class="notice info" role="status"><Icon name="check" size={18}/><p>{notice}</p></div>{/if}{#if error&&!open}<div class="notice error" role="alert">{error}</div>{/if}
<section class="panel manufacturer-library" aria-label="Herstellerunterlagen">
  <form class="toolbar" onsubmit={search}><div class="search-field"><Icon name="search" size={17}/><label class="sr-only" for="manufacturer-query">Herstellerunterlagen durchsuchen</label><input id="manufacturer-query" type="search" bind:value={query} onkeydown={event=>{if(event.key==='Enter'){event.preventDefault();void search(event);}}} placeholder="Hersteller, Modell oder Artikel …" maxlength="150"/></div><label class="sr-only" for="manufacturer-scope">Studio filtern</label><select id="manufacturer-scope" use:searchableSelect={scope} bind:value={scope}><option value="">Alle Studios</option>{#each Object.entries(manufacturerAssetScopes) as [value,label]}<option {value}>{label}</option>{/each}</select><label class="sr-only" for="manufacturer-kind">Dateiart filtern</label><select id="manufacturer-kind" use:searchableSelect={kind} bind:value={kind}><option value="">Alle Unterlagen</option>{#each Object.entries(manufacturerAssetKinds) as [value,label]}<option {value}>{label}</option>{/each}</select><button class="btn" type="submit">Suchen</button></form>
  <div class="manufacturer-rows">{#each data.records as row}<article class="manufacturer-row"><div class="resource-symbol"><Icon name={row.kind==='reference'?'image':row.kind==='model'?'box':'file'} size={23}/></div><div class="resource-copy"><h2>{row.name}</h2><p>{row.manufacturer_name}{row.article_reference?' · '+row.article_reference:''}</p><div class="resource-tags"><span>{manufacturerAssetKinds[row.kind as keyof typeof manufacturerAssetKinds]}</span><span>{manufacturerAssetScopes[row.studio_scope as keyof typeof manufacturerAssetScopes]}</span><span class:ready={row.status==='available'}>{status(row)}</span></div>{#if row.status==='available'}<p class="resource-use">{[row.use_planning?'Planvorlage':'',row.use_ai?'KI-Referenz':''].filter(Boolean).join(' · ')} · Originalfassung bleibt erhalten</p>{/if}</div><div class="resource-actions">{#if row.document_id}<a class="btn small" data-sveltekit-reload href={`/api/v1/documents/${row.document_id}/download?version=${row.document_version_id}`} target="_blank" rel="noreferrer">Original öffnen<Icon name="arrow" size={14}/></a>{/if}{#if row.status==='draft'}<button class="btn small" onclick={()=>start(row)}>{row.document_version_id?'Verwendung festlegen':'Datei ergänzen'}</button>{:else}<button class="btn small ghost" onclick={()=>archiveCandidate=row.id}>Ausblenden</button>{/if}</div>{#if archiveCandidate===row.id}<div class="archive-confirm"><p>„{row.name}“ aus der neuen Auswahl ausblenden? Bestehende Planungen behalten ihren Quellenbezug.</p><button class="btn small" onclick={()=>archiveCandidate=''}>Behalten</button><button class="btn small" disabled={busy} onclick={()=>archive(row)}>Aus Auswahl ausblenden</button></div>{/if}</article>{:else}<div class="empty-state"><div class="empty-icon"><Icon name="box" size={25}/></div><h3>{query||scope||kind?'Keine passenden Herstellerunterlagen':'Ihre Herstellerdaten an einem Ort'}</h3><p>{query||scope||kind?'Passen Sie Ihre Suche oder die Auswahl an.':'Fügen Sie Originaldateien hinzu, die im Planungsalltag wirklich gebraucht werden. Die Bibliothek gibt keine technische Fertigungsfreigabe.'}</p>{#if !query&&!scope&&!kind}<button class="btn primary" onclick={()=>start()}>Erste Herstellerunterlage hinzufügen</button>{:else}<a class="btn" href="/manufacturer-assets">Auswahl zurücksetzen</a>{/if}</div>{/each}</div>
  {#if data.summary.manufacturerLibrary?.hasMore}<footer class="panel-footer"><a class="btn" href={next()}>Weitere Unterlagen<Icon name="arrow" size={15}/></a></footer>{/if}
</section>

{#if open}<div class="modal-backdrop" role="presentation" onclick={event=>{if(event.target===event.currentTarget)close();}}><div class="modal" role="dialog" aria-modal="true" aria-labelledby="manufacturer-editor-title" use:modalFocus tabindex="-1" onkeydown={event=>{if(event.key==='Escape')close();}}><header class="modal-header"><div><h2 id="manufacturer-editor-title">{stage===1?'Herstellerunterlage hinzufügen':'Datei & Verwendung prüfen'}</h2><p>Schritt {stage} von 2 · {stage===1?'Original und Zuordnung':'Dateiprüfung und erlaubte Nutzung'}</p></div><button class="icon-button" aria-label="Herstellerdialog schließen" disabled={busy} onclick={close}><Icon name="close"/></button></header>
  {#if stage===1}<form onsubmit={save} style="display:contents"><div class="modal-body">
    <label class="asset-file"><Icon name="upload" size={23}/><span><strong>{file?.name??'Originaldatei auswählen'}</strong><small>PDF, PNG, JPG, WEBP, TIFF, SVG, DXF oder GLB · bis 40 MB</small></span><input bind:this={fileInput} type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.tif,.tiff,.svg,.dxf,.glb" onchange={chooseFile} disabled={busy}/></label>
    <div class="field-grid mt"><div class="field"><label for="asset-name">Bezeichnung *</label><input id="asset-name" bind:value={values.name} required maxlength="160" placeholder="Zum Beispiel Modellname · Draufsicht"/></div><div class="field"><label for="asset-manufacturer">Hersteller *</label><input id="asset-manufacturer" bind:value={values.manufacturer_name} required maxlength="120"/></div><div class="field"><label for="asset-article">Artikel / Modell</label><input id="asset-article" bind:value={values.article_reference} maxlength="120"/></div><div class="field"><label for="asset-scope">In welchem Studio? *</label><select id="asset-scope" use:searchableSelect={values.studio_scope} bind:value={values.studio_scope}>{#each Object.entries(manufacturerAssetScopes) as [value,label]}<option {value}>{label}</option>{/each}</select></div><div class="field"><label for="asset-kind">Wofür ist die Datei? *</label><select id="asset-kind" use:searchableSelect={values.kind} bind:value={values.kind}>{#each Object.entries(manufacturerAssetKinds) as [value,label]}<option {value}>{label}</option>{/each}</select></div>{#if values.kind==='plan'}<div class="field"><label for="asset-unit">Originaleinheit bei SVG / DXF</label><select id="asset-unit" use:searchableSelect={values.source_unit??''} value={values.source_unit??''} onchange={event=>values.source_unit=(event.currentTarget.value||null) as ManufacturerAssetInput['source_unit']}><option value="">Bei PDF / Foto nicht ableiten</option><option value="mm">Millimeter</option><option value="cm">Zentimeter</option><option value="m">Meter</option><option value="in">Zoll</option></select></div>{/if}</div>
    <details class="form-disclosure mt"><summary>Quellenlink & Hinweise ergänzen<Icon name="down" size={15}/></summary><div class="disclosure-body"><div class="field mb"><label for="asset-url">Originalquelle des Herstellers</label><input id="asset-url" type="url" bind:value={values.source_url} placeholder="https://…"/></div><div class="field"><label for="asset-notes">Hinweise zur Ausführung oder Herkunft</label><textarea id="asset-notes" bind:value={values.notes} maxlength="2000"></textarea></div></div></details>
    {#if notice}<div class="notice info mt" role="status">{notice}</div>{/if}{#if busy&&uploadAbort}<button type="button" class="btn mt" onclick={()=>uploadAbort?.abort()}>Dateiübertragung abbrechen</button>{/if}{#if error}<div class="notice error mt" role="alert">{error}</div>{/if}
  </div><footer class="modal-footer"><button type="button" class="btn" disabled={busy} onclick={close}>Abbrechen</button><button type="submit" class="btn primary" disabled={busy}>{busy?'Wird gespeichert …':'Speichern & Verwendung prüfen'}<Icon name="arrow" size={15}/></button></footer></form>
  {:else}<form onsubmit={publish} style="display:contents"><div class="modal-body"><div class="asset-summary"><Icon name="file" size={22}/><div><strong>{current?.name}</strong><p>{current?.manufacturer_name} · {current?.file_name??'Noch keine Originaldatei'}</p></div></div>
    {#if !current?.document_version_id}<div class="notice warning mt">Ergänzen Sie zuerst die Originaldatei. Der Entwurf ist bereits gespeichert.</div>{:else if !fileReady}<div class="notice warning mt"><div><strong>Dateiprüfung noch offen</strong><p>Die Originaldatei bleibt privat. Nach bestandener Virenprüfung kann sie für die Studios bereitgestellt werden.</p></div></div>{:else}<div class="asset-checked"><Icon name="check" size={17}/>Originaldatei verfügbar · feste Dateiversion</div>{/if}
    <div class="inline-actions mt"><button type="button" class="btn small" disabled={busy} onclick={()=>stage=1}>Angaben / Datei ergänzen</button><button type="button" class="btn small" disabled={busy} onclick={()=>invalidateAll()}><Icon name="refresh" size={14}/>Dateistatus aktualisieren</button></div>
    <fieldset class="usage-options" disabled={busy}><legend>Erlaubte Verwendung</legend><label><input type="checkbox" bind:checked={usePlanning}/><span>In der Planung verwenden<small>PDF oder Foto als Planvorlage; SVG / DXF als prüfbare Kontur. 3D-Originale bleiben in der Bibliothek verfügbar.</small></span></label><label><input type="checkbox" bind:checked={useAI} disabled={!canAI}/><span>Als KI-Referenz verwenden<small>Die Datei darf bewusst als Bild- oder Textreferenz an den KI-Anbieter übermittelt werden.{!canAI?' Dafür wird ein PDF oder Bild benötigt.':''}</small></span></label></fieldset>
    <div class="field"><label for="asset-rights">Woraus ergibt sich die Nutzungsberechtigung? *</label><textarea id="asset-rights" bind:value={rights} required minlength="20" maxlength="2000" placeholder="Zum Beispiel Herstellerfreigabe vom … für interne Planung und KI-Referenzen. Quelle und Umfang konkret benennen."></textarea></div><label class="check-field mt"><input type="checkbox" bind:checked={confirmed} required/><span>Ich habe Quelle, Studiozuordnung und die genannten Nutzungsrechte geprüft.</span></label>
    <p class="field-help mt">Die Bereitstellung macht die Datei in den Studios auswählbar. Originaleinheiten, Maßstab und technische Eignung werden beim Einsatz weiter geprüft.</p>{#if error}<div class="notice error mt" role="alert">{error}</div>{/if}
  </div><footer class="modal-footer"><button type="button" class="btn" disabled={busy} onclick={close}>Für später schließen</button><button class="btn primary" type="submit" disabled={busy||!fileReady||!confirmed||(!usePlanning&&!useAI)}>{busy?'Wird bereitgestellt …':'In den Studios bereitstellen'}</button></footer></form>{/if}
</div></div>{/if}

<style>
  .library-intro{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-bottom:24px}.library-intro>div{display:flex;gap:11px;align-items:flex-start;padding:4px}.library-intro>div>span{display:grid;place-items:center;width:28px;height:28px;flex:none;border-radius:9px;background:var(--accent-wash);color:var(--forest);font-size:12px;font-weight:600}.library-intro p{font-size:12px;line-height:1.7}.library-intro strong{display:block;color:var(--ink);font-size:13px;margin-bottom:3px}
  .manufacturer-library .toolbar{gap:10px;border-bottom:1px solid var(--line)}.manufacturer-library :global(.searchable-select){max-width:230px}.manufacturer-row{display:flex;align-items:center;gap:16px;padding:23px 24px;border-bottom:1px solid var(--line-soft);flex-wrap:wrap}.resource-symbol{display:grid;place-items:center;flex:none;width:46px;height:50px;border-radius:13px;background:var(--wash);color:var(--forest)}.resource-copy{flex:1;min-width:220px}.resource-copy h2{font-size:15px;font-weight:600;margin:0 0 4px}.resource-copy p{font-size:12px;line-height:1.6}.resource-tags{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px}.resource-tags span{padding:3px 7px;font-size:10px;line-height:1.6;border-radius:6px;background:var(--wash);color:var(--muted)}.resource-tags .ready{background:var(--success-wash);color:var(--success)}.resource-copy .resource-use{margin-top:8px;font-size:11px}.resource-actions{display:flex;gap:7px;flex-wrap:wrap}.archive-confirm{flex-basis:100%;padding:15px;background:var(--wash);border-radius:10px;font-size:13px}.archive-confirm p{margin-bottom:10px}.archive-confirm .btn{margin-right:8px}
  .asset-file{display:flex;align-items:center;gap:14px;padding:21px 18px;border:1px dashed var(--line);border-radius:13px;background:var(--input-surface);position:relative;cursor:pointer;overflow:hidden}.asset-file>span{flex:1;min-width:0}.asset-file strong{display:block;font-size:13px;overflow-wrap:anywhere}.asset-file small{display:block;font-size:11px;color:var(--muted);line-height:1.7;margin-top:5px}.asset-file input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer}.asset-file:focus-within{outline:2px solid var(--forest);outline-offset:3px}.asset-summary{display:flex;gap:12px;padding:18px;background:var(--wash);border-radius:12px;align-items:center}.asset-summary strong{font-size:14px}.asset-summary p{font-size:12px;margin-top:5px}.asset-checked{display:flex;align-items:center;gap:7px;color:var(--success);font-size:12px;margin-top:17px}.usage-options{border:0;padding:0;margin:26px 0}.usage-options legend{font-size:14px;font-weight:600;margin-bottom:8px}.usage-options label{display:flex;align-items:flex-start;gap:10px;padding:14px 0;font-size:13px}.usage-options input{flex:none;width:17px;height:17px;margin:3px 0;accent-color:var(--forest)}.usage-options small{display:block;margin-top:6px;color:var(--muted);font-size:12px;line-height:1.7}.modal .check-field{align-items:flex-start;font-size:12px;line-height:1.7}
  @media(max-width:760px){.library-intro{grid-template-columns:1fr;gap:8px}.library-intro>div{align-items:center}.library-intro strong{display:inline;margin-right:6px}.manufacturer-row{padding:18px;gap:12px}.resource-copy{min-width:190px}.resource-actions{flex-basis:100%;padding-left:58px}.manufacturer-library :global(.searchable-select){max-width:none;flex:1}}
</style>
